public sealed class EmailWorker(Channel<EmailJob> channel, IServiceScopeFactory scopes,
    ILogger<EmailWorker> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await foreach (var job in channel.Reader.ReadAllAsync(stoppingToken))
        {
            try
            {
                // Hosted services are singletons: create a scope for scoped services like DbContext.
                await using var scope = scopes.CreateAsyncScope();
                var sender = scope.ServiceProvider.GetRequiredService<IEmailSender>();
                await sender.SendAsync(job, stoppingToken);
            }
            catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
            {
                break;                                   // shutting down, not an error
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "Email job {JobId} failed", job.Id);  // keep the worker alive
            }
        }
    }
}

